type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Verify shape has exactly 2 elements
    assert_eq!(shape.len(), 2, "Shape must have exactly 2 elements");
    
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Verify both dimensions are positive
    assert!(r > 0 && c > 0, "Both dimensions must be positive");
    
    let a_len = a.len();
    
    // Verify that at least one dimension matches the array length
    assert!(
        r == a_len || c == a_len,
        "Array length must match either rows ({}) or columns ({})",
        r, c
    );
    
    let mut result = Vec::with_capacity(r);
    
    if r == a_len {
        // Treat as column vector: each row gets the same array
        for i in 0..r {
            let row = vec![a[i]; c];
            result.push(row);
        }
    } else {
        // c == a_len: treat as row vector
        for _ in 0..r {
            result.push(a.clone());
        }
    }
    
    result
}